package main

import (
	"fmt"
	"os"
)

func LoadDatabaseURL() (string, error) {
	v := os.Getenv("DATABASE_URL")
	if v == "" {
		return "", fmt.Errorf("missing required environment variable: %s", "DATABASE_URL")
	}
	return v, nil
}

func LoadAPIKey() (string, error) {
	v := os.Getenv("API_KEY")
	if v == "" {
		return "", fmt.Errorf("missing required environment variable: %s", "API_KEY")
	}
	return v, nil
}

func LoadRegion() (string, error) {
	v := os.Getenv("REGION")
	if v == "" {
		return "", fmt.Errorf("missing required environment variable: %s", "REGION")
	}
	return v, nil
}

