package main

import (
	"os"
	"strings"
	"testing"
)

func TestLoadersReturnSetValue(t *testing.T) {
	os.Setenv("DATABASE_URL", "postgres://x")
	defer os.Unsetenv("DATABASE_URL")

	got, err := LoadDatabaseURL()
	if err != nil || got != "postgres://x" {
		t.Fatalf("LoadDatabaseURL() = %q, %v", got, err)
	}
}

func TestLoadersErrorWhenUnset(t *testing.T) {
	os.Unsetenv("API_KEY")

	_, err := LoadAPIKey()
	if err == nil {
		t.Fatal("expected an error when API_KEY is unset")
	}
	if !strings.Contains(err.Error(), "API_KEY") {
		t.Fatalf("error message must name the missing variable API_KEY, got: %v", err)
	}
}

func TestEachLoaderNamesItsOwnVariable(t *testing.T) {
	os.Unsetenv("REGION")
	_, err := LoadRegion()
	if err == nil || !strings.Contains(err.Error(), "REGION") {
		t.Fatalf("expected an error naming REGION, got: %v", err)
	}

	os.Unsetenv("DATABASE_URL")
	_, err = LoadDatabaseURL()
	if err == nil || !strings.Contains(err.Error(), "DATABASE_URL") {
		t.Fatalf("expected an error naming DATABASE_URL, got: %v", err)
	}
}

